    mime='image/png' if path.suffix=='.png' else 'image/jpeg'
    return '<figure><img loading="lazy" alt="'+e(caption)+'" src="data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()+'"><figcaption>'+e(caption)+'</figcaption></figure>'
